// Writes docs/data-report.md: who was left out and why, and what was estimated (WORLD-003, WORLD-004).
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { excludedBirths } from "../../src/engine/world/excluded";
import type { Country, CountryIndex } from "../../src/engine/world/types";

export function reportText(countries: Country[], index: CountryIndex): string {
  const lines: string[] = [
    "# Data report",
    "",
    "Generated by `npm run data`. Do not edit by hand.",
    "",
    `Data version **${index.dataVersion}**. **${countries.length}** countries are included and **${index.excluded.length}** are left out.`,
    "",
    "## Excluded countries",
    "",
    "A country is left out when it lacks a core indicator: a UN WPP life table, births, World Bank PIP income percentiles, a WHO cause-of-death mix, or an income group. The birth draw weights the included countries by births, so the excluded countries' share of births is redistributed.",
    "",
  ];
  if (index.excluded.length) {
    const births = excludedBirths(index);
    lines.push(
      `Births in the excluded countries: ${births.excluded.toLocaleString("en-US")} of ${births.total.toLocaleString("en-US")} a year (${(births.share * 100).toFixed(1)}%) in ${births.year}, UN WPP.`,
      "",
    );
    lines.push("| Code | Country | Missing |", "| --- | --- | --- |");
    for (const e of index.excluded) lines.push(`| ${e.iso3} | ${e.name} | ${e.missing.join(", ")} |`);
  } else lines.push("None.");

  const counts = new Map<string, number>();
  const walk = (node: unknown, path: string) => {
    if (typeof node !== "object" || node === null) return;
    if ("source" in node && "year" in node) {
      if ((node as { estimated?: boolean }).estimated) counts.set(path, (counts.get(path) ?? 0) + 1);
      return;
    }
    for (const [key, child] of Object.entries(node)) walk(child, path ? `${path}.${key}` : key);
  };
  countries.forEach((c) => walk({ ...c, iso3: undefined, name: undefined }, ""));

  lines.push(
    "",
    "## Estimated values",
    "",
    "Secondary indicators missing for an included country are filled from the population-weighted average of its region, then income group, then the world, and flagged `estimated`. The game never cites an estimated value as a fact about a country.",
    "",
    "| Indicator | Countries estimated | Share |",
    "| --- | --- | --- |",
  );
  for (const [path, n] of [...counts].sort())
    lines.push(`| ${path} | ${n} | ${Math.round((n / countries.length) * 100)}% |`);
  lines.push("");
  return lines.join("\n");
}

export function writeReport(countries: Country[], index: CountryIndex) {
  writeFileSync(join(process.cwd(), "docs", "data-report.md"), reportText(countries, index));
}
